<?php declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$signedIn=currentUser();if($signedIn)redirect(($signedIn['role']??'')==='admin'?'admin/index.php':'index.php');$error='';if(post()){verifyCsrf();$identifier=mb_strtolower(trim((string)($_POST['identifier']??'')));$pass=(string)($_POST['password']??'');$s=db()->prepare('SELECT * FROM users WHERE (email=? OR username=?) LIMIT 1');$s->execute([$identifier,$identifier]);$u=$s->fetch();if($u&&password_verify($pass,$u['password_hash'])){if(!(int)$u['is_active'])$error='This account is inactive. Contact an administrator.';elseif((int)$u['is_banned'])$error='This account has been banned.';else{loginUser($u);db()->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$u['id']]);redirect(($u['role']??'')==='admin'?'admin/index.php':'index.php');}}else{$error='Invalid username/email or password.';}}$pageTitle='Login';require __DIR__.'/includes/header.php';?><div class="form-shell"><p class="eyebrow">Welcome back</p><h1>Sign in</h1><p class="copy">Use your username or email address. New accounts remain read-only until an administrator verifies the email.</p><?php if($error):?><div class="flash error" style="position:static;margin:12px 0"><?=e($error)?></div><?php endif;?><form method="post"><?=csrfField()?><div class="field"><label>Username or email</label><input name="identifier" autocomplete="username" required></div><div class="field"><label>Password</label><input type="password" name="password" autocomplete="current-password" required></div><button class="btn primary">Sign in</button></form><p>New here? <a style="color:var(--forest);font-weight:800" href="register.php">Create an account</a></p></div><?php require __DIR__.'/includes/footer.php';
